package com.jbrempresa.backend.controller;
import com.jbrempresa.backend.dto.mensajeria.MensajeriaDtos.*;import com.jbrempresa.backend.service.MensajeriaInternaService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;import java.util.Map;
@RestController@RequestMapping("/mensajeria-interna")@CrossOrigin(origins="http://localhost:4200") public class MensajeriaInternaController{private final MensajeriaInternaService s;public MensajeriaInternaController(MensajeriaInternaService s){this.s=s;}@GetMapping("/destinatarios")public List<Destinatario> destinatarios(){return s.destinatarios();}@GetMapping("/conversaciones")public List<Conversacion> conversaciones(){return s.conversaciones();}@GetMapping("/conversaciones/bajas")public List<Conversacion> bajas(){return s.bajas();}@GetMapping("/conversaciones/{id}/mensajes")public List<Mensaje> mensajes(@PathVariable Long id,@RequestParam(defaultValue="true")boolean marcarLeido){return s.mensajes(id,marcarLeido);}@PatchMapping("/conversaciones/{id}/lectura")public Conversacion lectura(@PathVariable Long id,@RequestBody Map<String,Boolean> in){return s.lectura(id,Boolean.TRUE.equals(in.get("leida")));}@GetMapping("/no-leidos")public Map<String,Long> noLeidos(){return Map.of("total",s.noLeidos());}@PostMapping("/conversaciones")public Conversacion crear(@Valid@RequestBody NuevaConversacion in){return s.crear(in);}@PostMapping("/conversaciones/{id}/mensajes")public Mensaje responder(@PathVariable Long id,@Valid@RequestBody NuevoMensaje in){return s.responder(id,in);}@PutMapping("/mensajes/{id}")public Mensaje editar(@PathVariable Long id,@Valid@RequestBody EditarMensaje in){return s.editar(id,in);}@PatchMapping("/conversaciones/{id}/baja")public void baja(@PathVariable Long id){s.darBaja(id);}@PatchMapping("/conversaciones/{id}/reactivacion")public Conversacion reactivar(@PathVariable Long id){return s.reactivar(id);}@DeleteMapping("/conversaciones/{id}")public void eliminar(@PathVariable Long id){s.eliminarDefinitivamente(id);}@DeleteMapping("/conversaciones")public Map<String,Integer> eliminarHasta(@RequestParam java.time.LocalDate hasta){return Map.of("eliminadas",s.eliminarHasta(hasta));}}
